                task: '<b>Досліджуємо горіння свічки</b> (експеримент для групи). Дотримуйтеся правил безпеки! Звичайні свічки виготовляють з парафіну — суміші речовин із загальною формулою C<sub><i>n</i></sub>H<sub><i>m</i></sub>. Кожна речовина згоряє, як і метан, з утворенням вуглекислого газу й води. Переконайтеся в цьому, виконавши дослід.<br>Потрібні: свічка, дві склянки місткістю 200–250 мл, прозорий розчин гашеного вапна (вапняна вода).<br>Запаліть свічку. Візьміть одну склянку, переверніть догори дном і тримайте її на відстані 1–2 см від кінця полум’я (її можна закріпити в лабораторному штативі лапкою). За кілька хвилин на внутрішніх стінках склянки почнуть з’являтися краплинки води. Унаслідок яких хімічного і фізичного явищ утворюється вода?<br>Другу склянку змочіть усередині вапняною водою й тримайте догори дном над свічкою, щоб полум’я входило у склянку на 2–3 см. Краплі рідини на стінках склянки поступово стають каламутними внаслідок утворення нерозчинних дрібних часточок крейди. Це — продукт реакції вапна з вуглекислим газом (другим продуктом горіння парафіну). Запишіть у зошиті свої спостереження і висновок.',
