                task: '<b>Досліджуємо корозію заліза.</b> Підготуйте чотири однакові очищені залізні цвяхи і чотири маленькі склянки або прозорі пластикові стаканчики (у кожній ємності цвях має поміститися повністю).<br>В одну склянку налийте воду з водогону, яка контактувала з повітрям протягом доби, у другу — прокип’ячену і швидко охолоджену воду. Третю і четверту склянки заповніть заздалегідь виготовленим розчином кухонної солі з масовою часткою 2 % (він моделює морську воду).<br>У кожну склянку помістіть цвях. У другу і третю склянки налийте по чайній ложці олії (для запобігання контакту рідини з повітрям) та накрийте їх. Вміст першої та четвертої склянок періодично збовтуйте.<br>Зафіксуйте час (він може становити до кількох діб), через який з’являться ознаки корозії заліза в кожній рідині. Поясніть отримані результати і сформулюйте висновки.',
